function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.file).split(' M').map((d,i)=>`<path d="${i?'M':''}${d}"/>`).join('')}</svg>`;}
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5200);}
function saved(){try{return restoreState(localStorage.getItem(SAVE));}catch{return null;}}
function save(){try{localStorage.setItem(SAVE,JSON.stringify(state));}catch{toast('瀏覽器無法儲存；可從事件簿匯出本次紀錄。');}}
function setSettings(){document.documentElement.style.setProperty('--scale',settings.large?'1.12':'1');document.body.classList.toggle('large-text',settings.large);document.body.classList.toggle('reduced-motion',settings.motion);$('#sound-caption').hidden=!settings.captions;$('#sound-label').textContent=settings.sound?'音效開啟':'音效關閉';$('#sound-toggle').setAttribute('aria-label',settings.sound?'關閉音效':'開啟音效');$('#sound-toggle').setAttribute('aria-pressed',String(settings.sound));try{localStorage.setItem(SETTINGS,JSON.stringify(settings));}catch{}audio.setVolume();}
const audio={ctx:null,gain:null,init(){if(this.ctx)return;try{this.ctx=new (window.AudioContext||window.webkitAudioContext)();this.gain=this.ctx.createGain();this.gain.gain.value=0;this.gain.connect(this.ctx.destination);const oscillator=this.ctx.createOscillator();oscillator.type='sine';oscillator.frequency.value=74;const low=this.ctx.createGain();low.gain.value=.09;oscillator.connect(low);low.connect(this.gain);oscillator.start();const length=this.ctx.sampleRate*3,buffer=this.ctx.createBuffer(1,length,this.ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=Math.random()*2-1;const source=this.ctx.createBufferSource();source.buffer=buffer;source.loop=true;const filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=360;const noise=this.ctx.createGain();noise.gain.value=.09;source.connect(filter);filter.connect(noise);noise.connect(this.gain);source.start();}catch{toast('這個瀏覽器無法啟用合成音效，文字提示仍可使用。');}},setVolume(){if(this.gain)this.gain.gain.setTargetAtTime(settings.sound?settings.volume:0,this.ctx.currentTime,.12);},async resume(){this.init();if(this.ctx?.state==='suspended')await this.ctx.resume();this.setVolume();},click(){if(!settings.sound||!this.ctx)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.frequency.setValueAtTime(650,this.ctx.currentTime);o.frequency.exponentialRampToValueAtTime(340,this.ctx.currentTime+.07);g.gain.setValueAtTime(.025*settings.volume,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+.08);o.connect(g);g.connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+.08);}};
const LOCATIONS={dorm:{code:'RESIDENTIAL / B-02',title:'生活區寢室',description:'乾燥的床位，正常的通風。今天還沒有什麼不一樣。',caption:'通風機平穩運轉。隔床傳來輕微夢話。',machine:'PERSONAL LOCKER',interaction:'床邊置物櫃'},canteen:{code:'COMMUNAL / C-01',title:'公共餐廳',description:'暖燈、熱食，還有剛下夜班的人。',caption:'餐盤輕碰。抽風機運轉，後勤在核對留餐。',machine:'MEAL SERVICE',interaction:'配給窗口'},gate:{code:'ACCESS CONTROL / B-01',title:'守門控制室',description:'窗外是接收區，身後是大家生活的地方。',caption:'對講機待命。門機低鳴，位置感測器正常。',machine:'GATE INTERLOCK',interaction:'門禁工作台'},engineering:{code:'ENGINEERING / E-01',title:'工程維護區',description:'設備完整運作。維護，是讓平常日子繼續的工作。',caption:'泵浦規律轉動。工程師在檢查維修表。',machine:'SERVICE ACCESS',interaction:'工程巡檢窗口'}};
const b=(label,action,cls='secondary',data='')=>`<button class="${cls}" data-action="${action}" ${data}>${label}</button>`;
const ui=(label,panel,cls='secondary')=>`<button class="${cls}" data-ui="${panel}">${label}</button>`;
function actionItem(action,label,detail='',danger=false){const reason=can(state,action);return `<div class="action-item"><button class="${danger?'danger-button':'secondary'}" data-action="${action}" ${reason?'disabled':''}>${esc(label)}</button><small>${esc(reason||detail)}</small></div>`;}
