 for(const key of ['stamina','fatigue','pressure']){$(`#${key}`).textContent=state[key];$(`#${key}-meter`).value=state[key];$(`#${key}-meter`).setAttribute('aria-label',`${{stamina:'體力',fatigue:'疲勞',pressure:'壓力'}[key]} ${state[key]}`);}
 $$('.location-nav button').forEach(el=>{el.setAttribute('aria-current',state.location===el.dataset.move?'location':'false');el.disabled=state.ended;});$('#journal-dot').hidden=!state.events.length;
 const steps=[state.gear,state.rosterRead,state.signed,state.arrived,!!state.decision||state.held,state.ended];$('#progress').innerHTML=steps.map(done=>`<span class="${done?'complete':''}"></span>`).join('');
 let actions='';if(state.ended)actions=ui('查看首日回顧','result','primary')+ui('查看事件簿','journal');
 else if(state.location==='dorm'){actions=!state.gear?b('取工作裝備 · 4 分鐘','gear','primary'):ui('查看隨身裝備','inventory');actions+=ui('查看交班事項','roster');}
 else if(state.location==='canteen'){actions=state.ate?ui('與後勤交談','logistics'):b('領取早餐 · 15 分鐘','eat','primary');actions+=ui('工作名冊與交班','roster');if(state.delegated&&state.delegateDue)actions+=b('等候代理回報','wait');}
